namespace AnyCli;

/// <summary>
/// Describes how typed command parameters are configured and created.
/// </summary>
/// <typeparam name="TSelf">The parameters type.</typeparam>
/// <remarks>
/// Implementations are normally generated by the AnyCli source generator from
/// <see cref="ArgumentAttribute"/>, <see cref="VariadicArgumentAttribute"/>, and
/// <see cref="OptionAttribute"/> members.
/// </remarks>
public interface ICommandParameters<TSelf>
    where TSelf : class, ICommandParameters<TSelf>
{
    /// <summary>
    /// Defines the arguments and options for the parameter type.
    /// </summary>
    /// <param name="parameters">The parameters builder.</param>
    static abstract void Configure(CommandParameterDefinitionBuilder parameters);

    /// <summary>
    /// Creates typed parameters from parsed command parameter values.
    /// </summary>
    /// <param name="parameterValues">The parsed parameter values.</param>
    /// <returns>The parameters instance.</returns>
    static abstract TSelf Bind(ParsedCommandParameters parameterValues);
}
